```java
import java.util.Scanner;

class Solution {
    static class Node {
        int valor;
        Node esq, dir;

        Node(int valor) {
            this.valor = valor;
            this.esq = null;
            this.dir = null;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();

        Node root1 = null;
        Node root2 = null;

        // Constrói primeira árvore
        for (int i = 0; i < n; i++) {
            root1 = inserir(root1, in.nextInt());
        }

        // Constrói segunda árvore
        for (int i = 0; i < n; i++) {
            root2 = inserir(root2, in.nextInt());
        }

        boolean similares = saoSimilares(root1, root2);
        System.out.println(similares ? "Arvores similares." : "Arvores com estruturas diferentes.");
    }

    static Node inserir(Node raiz, int valor) {
        if (raiz == null) {
            return new Node(valor);
        }
        if (valor < raiz.valor) {
            raiz.esq = inserir(raiz.esq, valor);
        } else {
            raiz.dir = inserir(raiz.dir, valor);
        }
        return raiz;
    }

    static boolean saoSimilares(Node a, Node b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        return saoSimilares(a.esq, b.esq) && saoSimilares(a.dir, b.dir);
    }
}
