import java.util.*;

class Solution {
    static class Node {
        int value;
        Node left, right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    static class BST {
        Node root;

        BST() {
            this.root = null;
        }

        void add(int value) {
            if (root == null) {
                root = new Node(value);
            } else {
                addRecursive(root, value);
            }
        }

        private void addRecursive(Node node, int value) {
            if (value < node.value) {
                if (node.left == null) {
                    node.left = new Node(value);
                } else {
                    addRecursive(node.left, value);
                }
            } else {
                if (node.right == null) {
                    node.right = new Node(value);
                } else {
                    addRecursive(node.right, value);
                }
            }
        }

        List<Integer> findPredecessorPath(int target) {
            List<Integer> path = new ArrayList<>();
            Node predecessor = null;
            Node current = root;

            while (current != null) {
                path.add(current.value);

                if (target == current.value) {
                    break;
                } else if (target < current.value) {
                    current = current.left;
                } else {
                    predecessor = current;
                    current = current.right;
                }
            }

            // Se tem filho esquerdo, predecessor está na subárvore esquerda
            if (current != null && current.left != null) {
                predecessor = current.left;
                path.add(predecessor.value);

                // Vai até o nó mais à direita da subárvore esquerda
                while (predecessor.right != null) {
                    predecessor = predecessor.right;
                    path.add(predecessor.value);
                }
            }
            // Se não tem filho esquerdo e não encontrou predecessor no caminho
            else if (predecessor == null) {
                // Não há predecessor, retorna o caminho até o último nó visitado
            }

            return path;
        }
    }

