import java.util.*;

class Solution {
    static class Node {
        int value;
        Node left, right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    static class BST {
        Node root;

        BST() {
            this.root = null;
        }

        void add(int value) {
            if (root == null) {
                root = new Node(value);
            } else {
                addRecursive(root, value);
            }
        }

        private void addRecursive(Node node, int value) {
            if (value < node.value) {
                if (node.left == null) {
                    node.left = new Node(value);
                } else {
                    addRecursive(node.left, value);
                }
            } else {
                if (node.right == null) {
                    node.right = new Node(value);
                } else {
                    addRecursive(node.right, value);
                }
            }
        }

        List<Integer> findPredecessorPath(int target) {
            List<Integer> path = new ArrayList<>();
            Node predecessor = null;
            Node current = root;

            while (current != null) {
                path.add(current.value);

                if (target == current.value) {
                    // Encontrou o nó
                    if (current.left != null) {
                        // Predecessor está na subárvore esquerda
                        predecessor = findMax(current.left, path);
                    }
                    break;
                } else if (target < current.value) {
                    current = current.left;
                } else {
                    // Atualiza predecessor quando vai para esquerda
                    predecessor = current;
                    current = current.right;
                }
            }

            // Se não há predecessor, retorna o caminho completo
            if (predecessor == null) {
                return path;
            }

            // Remove elementos do caminho após o predecessor
            int predecessorIndex = path.indexOf(predecessor.value);
            if (predecessorIndex != -1) {
                return path.subList(0, predecessorIndex + 1);
            }

            return path;
        }

        private Node findMax(Node node, List<Integer> path) {
            while (node.right != null) {
                path.add(node.value);
                node = node.right;
            }
            path.add(node.value);
            return node;
        }
    }

