public class Solution {

    public static int extractThreeDigits(int number, int position) {
        // position: 1 = dígitos 1-3 (mais à direita), 4 = dígitos 4-6, etc.
        int startDigit = position;
        int endDigit = position + 2;

        // Remove os dígitos à direita do trio
        int temp = number / (int)Math.pow(10, startDigit - 1);

        // Pega apenas os 3 dígitos necessários
        int result = temp % 1000;

        return result;
    }

    public static int[] countingSort(int[] arr, int position) {
        int n = arr.length;
        int[] output = new int[n];

        // Encontra o valor máximo para este position
        int max = 0;
        for (int num : arr) {
            int digits = extractThreeDigits(num, position);
            max = Math.max(max, digits);
        }

        // Array de contagem
        int[] count = new int[max + 1];

        // Conta as ocorrências
        for (int num : arr) {
            int digits = extractThreeDigits(num, position);
            count[digits]++;
        }

        // Soma cumulativa
        for (int i = 1; i <= max; i++) {
            count[i] += count[i - 1];
        }

        // Constrói o array ordenado (ordem inversa para estabilidade)
        for (int i = n - 1; i >= 0; i--) {
            int digits = extractThreeDigits(arr[i], position);
            output[count[digits] - 1] = arr[i];
            count[digits]--;
        }

        return output;
    }

