        if (root == null) {
            root = new Node(value);
        } else {
            root.add(value);
        }
    }

    public void preOrder(List<Integer> list) {
        if (root != null) {
            root.preOrder(list);
        }
    }

    public int countGreaterThan(int n) {
        return countGreaterThan(root, n);
    }

    private int countGreaterThan(Node node, int n) {
        if (node == null) return 0;

        if (node.value > n) {
            // Nó atual é maior que N, então contamos este nó
            // e todos os nós da subárvore direita (que são todos maiores)
            // mas precisamos verificar a subárvore esquerda
            return 1 + countGreaterThan(node.left, n) + count(node.right);
        } else {
            // Nó atual é menor ou igual a N, então só verificamos a subárvore direita
            return countGreaterThan(node.right, n);
        }
    }

    private int count(Node node) {
        if (node == null) return 0;
        return 1 + count(node.left) + count(node.right);
    }
}

