        // Ler os nós do grafo
        String[] nodes = scanner.nextLine().split(" ");

        // Criar o hashmap para armazenar as arestas
        HashMap<String, Integer> graph = new HashMap<>();

        // Ler a matriz de adjacência
        for (int i = 0; i < nodes.length; i++) {
            String[] weights = scanner.nextLine().split(" ");

            for (int j = 0; j < weights.length; j++) {
                int weight = Integer.parseInt(weights[j]);
                if (weight != 0) {
                    // Para grafos não dirigidos, usar sempre a mesma ordenação
                    // (lexicográfica) para evitar duplicação
                    String edge;
                    if (nodes[i].compareTo(nodes[j]) <= 0) {
                        edge = nodes[i] + nodes[j];
                    } else {
                        edge = nodes[j] + nodes[i];
                    }
                    graph.put(edge, weight);
                }
            }
        }

        // Processar consultas
        while (scanner.hasNext()) {
            String query = scanner.next();
            if (query.equals("fim")) {
                break;
            }

            // Normalizar a consulta para grafos não dirigidos
            String normalizedQuery;
            if (query.length() == 2 && query.charAt(0) > query.charAt(1)) {
                normalizedQuery = "" + query.charAt(1) + query.charAt(0);
            } else {
                normalizedQuery = query;
            }

            if (graph.containsKey(normalizedQuery)) {
                System.out.println(graph.get(normalizedQuery));
            } else {
                System.out.println("aresta inexistente.");
            }
        }

        scanner.close();
    }
}
