class TabelaHash {
    private Pair[] tabela;

    public TabelaHash(int tamanho) {
        this.tabela = new Pair[tamanho];
    }

    private int hash(int chave) {
        return chave % tabela.length;
    }

    public void put(int chave, String valor) {
        // Verifica se a tabela está cheia
        boolean cheia = true;
        for (Pair p : tabela) {
            if (p == null || p.key == null) {
                cheia = false;
                break;
            }
        }

        if (cheia) {
            imprimir();
            return;
        }

        int posicao = hash(chave);

        // Probing linear
        for (int i = 0; i < tabela.length; i++) {
            int indice = (posicao + i) % tabela.length;

            if (tabela[indice] == null || tabela[indice].key == null) {
                tabela[indice] = new Pair(chave, valor);
                return;
            } else if (tabela[indice].key == chave) {
                // Atualiza valor existente
                tabela[indice].value = valor;
                return;
            }
        }
    }

    public void remove(int chave) {
        int posicao = hash(chave);

        for (int i = 0; i < tabela.length; i++) {
            int indice = (posicao + i) % tabela.length;

            if (tabela[indice] != null && tabela[indice].key != null && tabela[indice].key == chave) {
                tabela[indice].key = null;
                tabela[indice].value = null;
                return;
            }
        }
    }

