            }
        }
        Collections.sort(chaves);
        return chaves.toString();
    }

    public String values() {
        List<String> valores = new ArrayList<>();
        for (Pair p : tabela) {
            if (p != null && p.key != null) {
                valores.add(p.value);
            }
        }
        Collections.sort(valores);
        return valores.toString();
    }

